mod pricing;
use axum::{extract::{Multipart, Path, State}, http::{StatusCode, header}, response::{Html, IntoResponse}, routing::{get, post, delete}, Json, Router};
use base64::{engine::general_purpose::STANDARD, Engine};
use rusqlite::{params, Connection};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{env, fs, net::SocketAddr, path::PathBuf, sync::Arc};
use tower_http::services::ServeDir;
use uuid::Uuid;

type ApiError = (StatusCode, String);
type ApiResult<T> = Result<T, ApiError>;
#[derive(Clone)] struct AppState { db: Arc<PathBuf>, uploads: Arc<PathBuf>, client: reqwest::Client }
#[derive(Deserialize)] struct NewProject { name: String, address: String, loss_type: String }
#[derive(Deserialize)] struct NewRoom { name: String, length_ft: f64, width_ft: f64, height_ft: f64 }
#[derive(Deserialize)] struct LineInput { description: String, category: String, quantity: f64, unit: String, unit_price: f64, source: String }
#[derive(Deserialize)] struct AnalyzeInput { notes: String }
#[derive(Serialize, Deserialize, Clone)] struct Proposal { description: String, category: String, quantity: f64, unit: String, rationale: String, confidence: String, evidence: String }
fn err(e: impl std::fmt::Display) -> ApiError { (StatusCode::BAD_REQUEST, e.to_string()) }
fn db(s: &AppState) -> ApiResult<Connection> { let c=Connection::open(&*s.db).map_err(err)?;c.execute_batch("PRAGMA foreign_keys=ON;").map_err(err)?;Ok(c) }
fn init(c: &Connection) -> ApiResult<()> { c.execute_batch("PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL,loss_type TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,name TEXT NOT NULL,length_ft REAL NOT NULL,width_ft REAL NOT NULL,height_ft REAL NOT NULL,FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS photos(id TEXT PRIMARY KEY,room_id TEXT NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',FOREIGN KEY(room_id) REFERENCES rooms(id));
CREATE TABLE IF NOT EXISTS lines(id TEXT PRIMARY KEY,room_id TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,quantity REAL NOT NULL,unit TEXT NOT NULL,unit_price REAL NOT NULL,source TEXT NOT NULL,FOREIGN KEY(room_id) REFERENCES rooms(id));
CREATE TABLE IF NOT EXISTS analyses(id TEXT PRIMARY KEY,room_id TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,provider TEXT NOT NULL,proposals TEXT NOT NULL,FOREIGN KEY(room_id) REFERENCES rooms(id));").map_err(err) }
fn rows(c: &Connection, sql: &str, key: &str) -> ApiResult<Vec<Value>> {
 let mut st=c.prepare(sql).map_err(err)?;
 let n=st.column_count(); let names=(0..n).map(|i|st.column_name(i).unwrap_or("").to_string()).collect::<Vec<_>>();
 let iter=st.query_map(params![key],|row| { let mut map=serde_json::Map::new(); for (i,name) in names.iter().enumerate() { let v: rusqlite::types::Value=row.get(i)?; let j=match v { rusqlite::types::Value::Null=>Value::Null,rusqlite::types::Value::Integer(x)=>json!(x),rusqlite::types::Value::Real(x)=>json!(x),rusqlite::types::Value::Text(x)=>json!(x),rusqlite::types::Value::Blob(_)=>Value::Null}; map.insert(name.clone(),j); } Ok(Value::Object(map)) }).map_err(err)?;
 iter.collect::<Result<Vec<_>,_>>().map_err(err)
}
async fn projects(State(s):State<AppState>)->ApiResult<Json<Value>> { let c=db(&s)?; Ok(Json(json!(rows(&c,"SELECT * FROM projects WHERE id != ?1 ORDER BY created_at DESC, rowid DESC", "")?))) }
async fn create_project(State(s):State<AppState>,Json(p):Json<NewProject>)->ApiResult<Json<Value>> { if p.name.trim().is_empty(){return Err(err("Project name required"));} let id=Uuid::new_v4().to_string(); db(&s)?.execute("INSERT INTO projects(id,name,address,loss_type) VALUES(?1,?2,?3,?4)",params![id,p.name,p.address,p.loss_type]).map_err(err)?;Ok(Json(json!({"id":id}))) }
async fn project(Path(id):Path<String>,State(s):State<AppState>)->ApiResult<Json<Value>> { let c=db(&s)?; let p=rows(&c,"SELECT * FROM projects WHERE id=?1",&id)?.into_iter().next().ok_or(err("Project not found"))?; let rooms=rows(&c,"SELECT *, length_ft*width_ft AS floor_sf,2*(length_ft+width_ft)*height_ft AS wall_sf FROM rooms WHERE project_id=?1 ORDER BY rowid",&id)?; let mut result=vec![]; let mut total=0.0;
 for mut r in rooms { let rid=r["id"].as_str().unwrap_or(""); let photos=rows(&c,"SELECT * FROM photos WHERE room_id=?1 ORDER BY rowid",rid)?;let lines=rows(&c,"SELECT *,ROUND(quantity*unit_price,2) AS total FROM lines WHERE room_id=?1 ORDER BY rowid",rid)?;let analyses=rows(&c,"SELECT * FROM analyses WHERE room_id=?1 ORDER BY rowid DESC",rid)?;total+=lines.iter().map(|x|x["total"].as_f64().unwrap_or(0.0)).sum::<f64>();r["photos"]=json!(photos);r["lines"]=json!(lines);r["analyses"]=json!(analyses);result.push(r); }
 Ok(Json(json!({"project":p,"rooms":result,"subtotal":(total*100.0).round()/100.0}))) }
async fn create_room(Path(pid):Path<String>,State(s):State<AppState>,Json(r):Json<NewRoom>)->ApiResult<Json<Value>> {if r.name.trim().is_empty()||[r.length_ft,r.width_ft,r.height_ft].iter().any(|v|!v.is_finite()||*v<=0.0||*v>10000.0){return Err(err("Provide a name and positive dimensions"));}let id=Uuid::new_v4().to_string();db(&s)?.execute("INSERT INTO rooms VALUES(?1,?2,?3,?4,?5,?6)",params![id,pid,r.name,r.length_ft,r.width_ft,r.height_ft]).map_err(err)?;Ok(Json(json!({"id":id}))) }
async fn upload(Path(rid):Path<String>,State(s):State<AppState>,mut multipart:Multipart)->ApiResult<Json<Value>> { let mut count=0;while let Some(field)=multipart.next_field().await.map_err(err)? {if field.name()!=Some("photos"){continue;}let mime=field.content_type().unwrap_or("").to_string();if !["image/jpeg","image/png","image/webp"].contains(&mime.as_str()){return Err(err("Only JPEG, PNG and WebP images are supported"));}let bytes=field.bytes().await.map_err(err)?;if bytes.len()>12*1024*1024{return Err(err("Each photo must be under 12 MB"));}let ext=match mime.as_str(){"image/jpeg"=>"jpg","image/png"=>"png",_=>"webp"};let id=Uuid::new_v4().to_string();let name=format!("{id}.{ext}");fs::write(s.uploads.join(&name),bytes).map_err(err)?;db(&s)?.execute("INSERT INTO photos(id,room_id,filename,mime) VALUES(?1,?2,?3,?4)",params![id,rid,name,mime]).map_err(err)?;count+=1;}Ok(Json(json!({"uploaded":count}))) }
async fn add_line(Path(rid):Path<String>,State(s):State<AppState>,Json(l):Json<LineInput>)->ApiResult<Json<Value>> {if l.description.trim().is_empty()||!l.quantity.is_finite()||!l.unit_price.is_finite()||l.quantity<0.0||l.unit_price<0.0{return Err(err("Invalid line item"));}let id=Uuid::new_v4().to_string();db(&s)?.execute("INSERT INTO lines VALUES(?1,?2,?3,?4,?5,?6,?7,?8)",params![id,rid,l.description,l.category,l.quantity,l.unit,l.unit_price,l.source]).map_err(err)?;Ok(Json(json!({"id":id}))) }
async fn remove_line(Path(id):Path<String>,State(s):State<AppState>)->ApiResult<Json<Value>>{db(&s)?.execute("DELETE FROM lines WHERE id=?1",params![id]).map_err(err)?;Ok(Json(json!({"ok":true}))) }
async fn analyze(Path(rid):Path<String>,State(s):State<AppState>,Json(input):Json<AnalyzeInput>)->ApiResult<Json<Value>> {
 let c=db(&s)?;let room=rows(&c,"SELECT *, length_ft*width_ft AS floor_sf,2*(length_ft+width_ft)*height_ft AS wall_sf FROM rooms WHERE id=?1",&rid)?.into_iter().next().ok_or(err("Room not found"))?;let photos=rows(&c,"SELECT * FROM photos WHERE room_id=?1",&rid)?;
 let key=env::var("OPENAI_API_KEY").unwrap_or_default();if key.is_empty(){return Err((StatusCode::PRECONDITION_REQUIRED,"AI not configured. Set OPENAI_API_KEY. You can still add and price line items manually; no analysis was fabricated.".into()));}
 let mut content=vec![json!({"type":"text","text":format!("You are an assisting property damage estimator. Room: {}. Approximate floor SF: {}, wall SF: {}. Loss notes: {}. Identify only VISIBLE damage and propose possible repair activities. Do not infer hidden damage, code requirements, dimensions from photos, or definitive causation. Quantities may use provided room dimensions only when justified, otherwise use zero and mark needs measurement. Respond with a JSON object containing proposals array; each proposal: description,category,quantity,unit,rationale,confidence (low/medium/high),evidence (photo references or inspection notes). Pricing is deliberately excluded. Max 12 proposals.",room["name"],room["floor_sf"],room["wall_sf"],input.notes)})];
 for p in photos.iter().take(8){let bytes=fs::read(s.uploads.join(p["filename"].as_str().unwrap_or(""))).map_err(err)?;let encoded=STANDARD.encode(bytes);let mime=p["mime"].as_str().unwrap_or("image/jpeg");content.push(json!({"type":"image_url","image_url":{"url":format!("data:{mime};base64,{encoded}"),"detail":"low"}}));}
 if photos.is_empty(){return Err(err("Upload at least one photo before AI analysis"));}
 let model=env::var("OPENAI_MODEL").unwrap_or_else(|_|"gpt-4.1-mini".into());let resp=s.client.post("https://api.openai.com/v1/chat/completions").bearer_auth(key).json(&json!({"model":model,"temperature":0.1,"response_format":{"type":"json_object"},"messages":[{"role":"user","content":content}]})).send().await.map_err(err)?;let status=resp.status();let body:Value=resp.json().await.map_err(err)?;if !status.is_success(){return Err((StatusCode::BAD_GATEWAY,format!("AI provider returned {status}: {}",body["error"]["message"].as_str().unwrap_or("unknown error"))));}
 let text=body["choices"][0]["message"]["content"].as_str().ok_or(err("No AI response content"))?;let parsed:Value=serde_json::from_str(text).map_err(err)?;let proposals=parsed["proposals"].as_array().ok_or(err("AI did not return proposals"))?;let clean=proposals.iter().take(12).filter_map(|v|serde_json::from_value::<Proposal>(v.clone()).ok()).collect::<Vec<_>>();let aid=Uuid::new_v4().to_string();db(&s)?.execute("INSERT INTO analyses(id,room_id,provider,proposals) VALUES(?1,?2,?3,?4)",params![aid,rid,model,serde_json::to_string(&clean).map_err(err)?]).map_err(err)?;Ok(Json(json!({"proposals":clean,"provider":model,"analysis_id":aid})))
}
async fn index()->Html<&'static str>{Html(include_str!("../web/index.html"))}
#[tokio::main]async fn main()->Result<(),Box<dyn std::error::Error>>{let data=PathBuf::from(env::var("QUANTIMATE_DATA").unwrap_or_else(|_|"data".into()));let uploads=data.join("uploads");fs::create_dir_all(&uploads)?;let dbpath=data.join("quantimate.db");let conn=Connection::open(&dbpath)?;init(&conn)?;pricing::init(&conn)?;let s=AppState{db:Arc::new(dbpath),uploads:Arc::new(uploads.clone()),client:reqwest::Client::new()};let app=Router::new().route("/",get(index)).route("/api/projects",get(projects).post(create_project)).route("/api/projects/:id",get(project)).route("/api/projects/:id/rooms",post(create_room)).route("/api/rooms/:id/photos",post(upload)).route("/api/rooms/:id/lines",post(add_line)).route("/api/rooms/:id/analyze",post(analyze)).route("/api/lines/:id",delete(remove_line)).route("/api/prices",get(pricing::observations)).route("/api/prices/import",post(pricing::import_csv)).route("/api/assemblies",get(pricing::assemblies)).route("/api/rooms/:id/assembly/preview",post(pricing::preview)).route("/api/rooms/:id/assembly/line",post(pricing::add_assembly_line)).nest_service("/uploads",ServeDir::new(uploads)).with_state(s);let addr=SocketAddr::from(([127,0,0,1],8765));println!("Quantimate running at http://{addr}");let listener=tokio::net::TcpListener::bind(addr).await?;axum::serve(listener,app).await?;Ok(())}
